.darma-loader-tw-radar-sweep { position: relative; display: inline-block; overflow: hidden; width: var(--loader-size, 64px); height: var(--loader-size, 64px); border-radius: 9999px; border: calc(var(--loader-size, 64px) * .025) solid color-mix(in srgb, var(--loader-color, #22c55e) 35%, transparent); background: radial-gradient(circle, transparent 54%, color-mix(in srgb, var(--loader-color, #22c55e) 14%, transparent) 55%); }
.darma-loader-tw-radar-sweep::after { content: ''; position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: 9999px; background: conic-gradient(from 0deg, color-mix(in srgb, var(--loader-color, #22c55e) 70%, transparent), transparent 90deg); animation: darma-loader-tw-radar-sweep-twSpin calc(var(--loader-speed, 1s) * 1.4) linear infinite; }
@keyframes darma-loader-tw-radar-sweep-twSpin { to { transform: rotate(360deg); } }

